@spec temperEditor_tree_spec  src=tests/specs/temperEditor_tree_spec.lua  loc=135  cases=4
@exercises library (lib), tuning (tuning), configManager (h.cm)
@surface   lib.seedIfEmpty, tuning.derive, cm:getAt, cm:set
@harness   mk

# Intent
  Pin-test for temperEditor's library tree. The built-in EDO catalogue is a
  seed source (cm:defaultFor); seedIfEmpty stocks the library tier from it, so
  the descriptor surfaces the catalogue under the Library folder (no Factory
  section). Selecting a library row must preview (not raise) so the first edit
  can fork to project. Instantiated over a harness cm with a lib service.

# Helpers
  @fn has(list, val)  @ 25-28
  @fn mkEditor(h)  @ 32-48
      -- Returns the editor and the list of confirms its modalHost was asked to open,
      -- so a case can assert a gesture landed silently.
  @fn scale(root)  @ 54-60
  @fn placedInBothTiers(harness)  @ 64-69
      -- A non-empty global tier makes seedIfEmpty a no-op; the catalogue plays no
      -- part in these two cases.

# Cases
  @case 'descriptor lists the seeded library catalogue and drops the synthetic floor'  [harness]  @ 73-83
  @case 'selecting a library row previews it without raising'  [harness]  @ 86-97
  @case 'publishing a placed temper sends the library the scale without the root'  [harness]  @ 100-116
  @case 'a root is not drift from the library scale, but a changed step is'  [harness]  @ 119-133

# Uses (outbound edges)
  @use call lib.seedIfEmpty  @ 39
  @use call tuning.derive  @ 59,129
  @use call cm:getAt  @ 108
  @use call cm:set  @ 129

